# The payload every Factory probe posts: TESTER's base sample through the one
# builder (payload_helpers.render_probe_payload defines _payload_for here).
def _declared_specs(models):
    import datetime as _dt, typing
    kinds = {int: "int", float: "float", bool: "bool",
             _dt.datetime: "datetime", _dt.date: "date", _dt.time: "time"}
    def _kind(hint):
        # Optional[X] declares X: the sample follows the declared type.
        args = [a for a in (getattr(hint, "__args__", None) or ()) if a is not type(None)]
        if getattr(hint, "__origin__", None) is typing.Union and len(args) == 1:
            hint = args[0]
        return kinds.get(hint, "str")
    out = {}
    for cap, cls in models.items():
        try:
            hints = typing.get_type_hints(cls)
        except Exception:
            hints = {}
        c = dict(getattr(cls, "CONSTRAINTS", {}) or {})
        out[cap] = {"entity": getattr(cls, "ENTITY", cap),
                    "fields": [{"name": n, "type": _kind(hints.get(n, str)), **c.get(n, {})}
                               for n in getattr(cls, "FIELDS", [])]}
    return out


STORE_NOTIFICATION_CHANNELS = frozenset({'webhook', 'email', 'slack', 'mcp'})
_DOMAIN_CHANNEL_SAMPLE = 'email'
_TYPE_ALIASES = {'str': 'str', 'text': 'str', 'string': 'str', 'int': 'int', 'integer': 'int', 'float': 'float', 'real': 'float', 'number': 'float', 'bool': 'bool', 'boolean': 'bool', 'datetime': 'datetime', 'timestamp': 'datetime', 'date': 'date', 'time': 'time', 'uuid': 'uuid', 'email': 'email', 'varchar': 'str', 'char': 'str', 'bigint': 'int', 'smallint': 'int', 'long': 'int', 'double': 'float', 'decimal': 'float', 'numeric': 'float', 'money': 'float', 'currency': 'float'}
_TEMPORAL_SAMPLES = {'datetime': '2026-09-03T10:00:00', 'date': '2026-09-03', 'time': '10:00:00'}
_SAMPLE_VALUES = {'str': 'sample', 'int': 1, 'float': 1.5, 'bool': True, 'datetime': '2026-09-03T10:00:00', 'date': '2026-09-03', 'time': '10:00:00', 'uuid': '00000000-0000-4000-8000-000000000001', 'email': 'guest@example.com'}


def sample_channel_value(allowed=None):
    """Schema-sample for a reminder / notification ``channel`` field.

    A bare str field used to sample as ``"sample"``. Live VetCare Hub
    ``automated_reminders`` (sess_67fe60f7) forwarded that into
    notification / event_bus and the Store raised
    ``RuntimeError: Unknown channel: sample``. Prefer a Store-known
    value from ``allowed_values``; otherwise ``email`` (domain-typical
    and Store-listed). ``prepare_block_input`` still rewrites placeholders
    and delivery channels that lack their extra fields onto ``mcp``.
    """
    if allowed:
        for cand in allowed:
            raw = str(cand).strip()
            if raw.lower() in STORE_NOTIFICATION_CHANNELS:
                return raw
        first = allowed[0]
        if isinstance(first, str) and first.strip():
            return first.strip()
    return _DOMAIN_CHANNEL_SAMPLE


def _resolve_known_field_type(raw):
    """Canonical type if WRITER/LLM spelling is known; None if unknown.

    TESTER sample emission must distinguish unknown types from ``str``.
    Mapping them to ``str`` hid ``datetime`` only because that alias is
    listed; a four-key literal map then KeyError'd (sess_f48f60b / BACKEND-S).
    """
    kind = str(raw or 'str').strip().lower()
    kind = kind.replace('datetime.', '').replace('uuid.', '').replace('decimal.', '').replace('optional[', '').replace(']', '')
    kind = ' | '.join((part for part in (p.strip() for p in kind.split('|')) if part and part != 'none'))
    kind = kind.split('(', 1)[0].strip()
    if not kind:
        return 'str'
    return _TYPE_ALIASES.get(kind)


def _normalize_field_type(raw):
    """Map LLM/SQL/annotation spellings onto the emitter's type set."""
    return _resolve_known_field_type(raw) or 'str'


def _looks_like_email_field(field):
    """The field DECLARES an address: type ``email`` or format ``email``.

    The live winery-hospitality export failed its own pilot suite because
    TESTER sent guest_email='sample' and WRITER (correctly) required '@'.
    The fix is the declaration (type/format), never the field's name: a
    name implies nothing the spec did not say.
    """
    resolved = _resolve_known_field_type(field.get('type') or 'str')
    if resolved == 'email':
        return True
    if resolved not in (None, 'str'):
        return False
    fmt = str(field.get('format') or '').lower().replace('-', '')
    return fmt == 'email'


def _temporal_sample(field):
    """ISO sample for a field DECLARED temporal (type or format), else None.

    Live veterinary-care: scheduled_time / duration_minutes / service_type.
    The word "sample" is type-valid as str and rejected as a time -- so the
    spec declares the type; the name decides nothing.
    """
    fmt = str(field.get('format') or '').lower().replace('-', '')
    ftype = _normalize_field_type(field.get('type') or 'str')
    if ftype == 'datetime' or fmt in ('datetime', 'timestamp', 'iso8601'):
        return _TEMPORAL_SAMPLES['datetime']
    if ftype == 'date' or fmt == 'date':
        return _TEMPORAL_SAMPLES['date']
    if ftype == 'time' or fmt == 'time':
        return _TEMPORAL_SAMPLES['time']
    return None


def _sample_value(field):
    """A value that satisfies every constraint the field DECLARES.

    Typing alone is not enough. An agent-designed field often carries a
    vocabulary or a range, and a generic "sample" is type-valid but
    domain-invalid -- the route rejects it, the gate fails, and the rework
    loop cannot recover because the only way for the writer to pass would be
    to delete its own validation. What the field is CALLED decides nothing:
    a vocabulary, a type, a format or a bound must be declared (the spec
    miner aligns the spec to what the handler enforces), and a field that
    declares nothing gets its type's neutral sample.
    """
    if field.get('allowed_values'):
        return sample_channel_value(field['allowed_values'])
    if _looks_like_email_field(field):
        return 'guest@example.com'
    temporal = _temporal_sample(field)
    if temporal is not None:
        return temporal
    ftype = _normalize_field_type(field.get('type') or 'str')
    if ftype in ('int', 'float'):
        lo, hi = (field.get('min'), field.get('max'))
        if lo is not None:
            if lo <= 0 and (hi is None or hi >= 1):
                return 1 if ftype == 'int' else 1.0
            return lo
        if hi is not None:
            return hi if hi < _SAMPLE_VALUES[ftype] else _SAMPLE_VALUES[ftype]
    return _SAMPLE_VALUES.get(ftype, 'sample')


def _sample_payload(spec):
    """A valid instance of the entity, built from its own spec.

    Includes every declared field (required and optional) so pilot
    ``test_every_capability_route_accepts_payload`` never omits a column the
    route/handler guard demands. Values honour vocabulary, bounds, and
    email-shaped names via ``_sample_value``.
    """
    out = {}
    for field in spec.get('fields', []) or []:
        if not isinstance(field, dict) or not field.get('name'):
            continue
        if 'type' not in field:
            field = {**field, 'type': 'str'}
        out[str(field['name'])] = _sample_value(field)
    return out


import dataclasses as _dataclasses
import json as _json

_SAMPLE_BY_TYPE = {'str': 'sample', 'int': 1, 'float': 1.5, 'bool': True}
_ACCEPT_STATUSES = (200,)
_OK_KEY = 'ok'


def _model_of(capability_id):
    try:
        from app.models import MODELS
    except Exception:
        return None
    return MODELS.get(capability_id)


def _field_sample(capability_id, field):
    """A value the product's own model declares acceptable for ``field``."""
    cls = _model_of(capability_id)
    if cls is None:
        return None
    rules = (getattr(cls, 'CONSTRAINTS', {}) or {}).get(field) or {}
    allowed = rules.get('allowed_values')
    if allowed:
        return allowed[0]
    default = None
    if _dataclasses.is_dataclass(cls):
        attr = (getattr(cls, '_FIELD_PY', {}) or {}).get(field, field)
        for f in _dataclasses.fields(cls):
            if f.name != attr:
                continue
            if f.default is not _dataclasses.MISSING:
                default = f.default
            elif f.default_factory is not _dataclasses.MISSING:
                default = f.default_factory()
    low = rules.get('min')
    if default not in (None, '') and not isinstance(default, bool):
        if not isinstance(default, (int, float)) or default:
            if low is None or not isinstance(default, (int, float)) or default >= low:
                return default
    sample = _SAMPLE_BY_TYPE.get(type(default).__name__, _SAMPLE_BY_TYPE['str'])
    if low is not None and isinstance(sample, (int, float)) and sample < low:
        sample = low
    return sample


def _sample_payload_for(capability_id, base):
    """The Factory spec sample, completed with every field the product's
    own model declares required and the sample lacks."""
    payload = dict(base or {})
    cls = _model_of(capability_id)
    if cls is None:
        return payload
    constraints = getattr(cls, 'CONSTRAINTS', {}) or {}
    for name in list(getattr(cls, 'FIELDS', []) or []):
        if not (constraints.get(name) or {}).get('required'):
            continue
        if payload.get(name) in (None, ''):
            value = _field_sample(capability_id, name)
            if value not in (None, ''):
                payload[name] = value
    return payload


def _rejection(resp):
    """The rejection as data: (field, reason, allowed) or None. Read from
    the structured rejection the product states -- headers on a 422,
    keys on an ok:false body -- never from prose or JSON text, so no
    token in a response body can leak into a payload."""
    field = resp.headers.get('X-Rejected-Field')
    if field is not None:
        try:
            field = _json.loads(field)
        except ValueError:
            return None
        reason = resp.headers.get('X-Rejection-Reason')
        allowed = resp.headers.get('X-Allowed-Values')
        try:
            allowed = _json.loads(allowed) if allowed is not None else None
        except ValueError:
            allowed = None
        return field, reason, allowed
    try:
        body = resp.json()
    except Exception:
        return None
    if not isinstance(body, dict) or 'rejected_field' not in body:
        return None
    return (body.get('rejected_field'), body.get('rejection_reason'),
            body.get('allowed_values'))


def _post_accepting(path, payload, headers, capability_id=None):
    """POST the completed payload; when the product refuses a field AS
    DATA, adopt the value its own model declares and retry. Returns
    (response, corrections). Each (field, value) is tried at most once,
    so the loop converges or stops. A refusal that is not a field
    rejection (a 503 placeholder refusal, a 401) is returned as is."""
    payload = _sample_payload_for(capability_id, payload)
    corrections = []
    tried = set()
    resp = client.post(path, json=payload, headers=headers)
    for _ in range(len(payload) + 2):
        failed = resp.status_code not in _ACCEPT_STATUSES
        if not failed:
            try:
                failed = resp.json().get(_OK_KEY) is False
            except Exception:
                failed = False
        if not failed:
            break
        rejection = _rejection(resp)
        if rejection is None:
            break
        field, reason, allowed = rejection
        if not isinstance(field, str) or not field:
            break
        if reason == 'not_allowed' and isinstance(allowed, list) and allowed:
            value = allowed[0]
        elif reason == 'missing_required':
            value = _field_sample(capability_id, field)
            if value in (None, ''):
                break
        else:
            break
        key = (field, repr(value))
        if key in tried:
            break
        tried.add(key)
        corrections.append(
            str(field) + '=' + repr(payload.get(field)) + '->' + repr(value)
        )
        payload[field] = value
        resp = client.post(path, json=payload, headers=headers)
    if _still_failed(resp):
        _record_capability_failure(capability_id)
    return resp, corrections


def _still_failed(resp):
    if resp.status_code not in _ACCEPT_STATUSES:
        return True
    try:
        return resp.json().get(_OK_KEY) is False
    except Exception:
        return False


import json as _cap_json
