def _probe_excepthook(typ, exc, tb):
    if issubclass(typ, SystemExit):
        return sys.__excepthook__(typ, exc, tb)
    _record("halt", "crash", HALTS.get("crash", "crash"))
    _record("finding", "crash", _exc_text(exc))
    return sys.__excepthook__(typ, exc, tb)

