"""Payloads, boundaries and vocabularies built from the product's own spec.

``app.domain_ops.SPECS`` is the declaration every capability is graded
against, so the writer's own suite builds its cases from it instead of
carrying a second, hand-typed copy of the schema that can drift away from
the product. Nothing here is keyed on a capability id: a case is derived
from what the field DECLARES (a vocabulary, a bound, a type).
"""

from __future__ import annotations

from typing import Any, Dict, List, Tuple

from app.domain_ops import SPECS

FALLBACK_SAMPLE = "sample"


def spec_for(capability_id: str) -> Dict[str, Any]:
    return dict(SPECS.get(capability_id) or {})


def fields(capability_id: str) -> List[Dict[str, Any]]:
    return [dict(item) for item in (spec_for(capability_id).get("fields") or [])]


def field_names(capability_id: str) -> List[str]:
    return [str(item["name"]) for item in fields(capability_id)]


def sample_value(field: Dict[str, Any]) -> Any:
    """A value the field's own declaration accepts."""
    allowed = field.get("allowed_values")
    if allowed:
        return allowed[0]
    kind = str(field.get("type") or "str").lower()
    if kind in ("int", "float"):
        low, high = field.get("min"), field.get("max")
        if low is not None and (high is None or high >= 1):
            value = 1
        elif low is not None:
            value = low
        elif high is not None:
            value = high
        else:
            value = 1
        return int(value) if kind == "int" else float(value)
    if kind == "bool":
        return False
    return FALLBACK_SAMPLE


def payload(capability_id: str, **overrides: Any) -> Dict[str, Any]:
    body = {str(item["name"]): sample_value(item) for item in fields(capability_id)}
    body.update(overrides)
    return body


def capability_ids() -> List[str]:
    return sorted(SPECS)


def numeric_fields(capability_id: str) -> List[Dict[str, Any]]:
    return [
        item
        for item in fields(capability_id)
        if str(item.get("type") or "").lower() in ("int", "float")
    ]


def enum_fields(capability_id: str) -> List[Dict[str, Any]]:
    return [item for item in fields(capability_id) if item.get("allowed_values")]


def required_fields(capability_id: str) -> List[str]:
    return [str(item["name"]) for item in fields(capability_id) if item.get("required")]


def boundary_pairs(capability_id: str) -> List[Tuple[str, Any, Any]]:
    """(field, value exactly on the line, value outside it) per bound.

    Exercised on the line rather than either side of it: a rule stated as
    ``min``/``max`` is a rule about the line itself.
    """
    out: List[Tuple[str, Any, Any]] = []
    for item in numeric_fields(capability_id):
        name = str(item["name"])
        kind = str(item.get("type") or "float").lower()
        cast = int if kind == "int" else float
        low, high = item.get("min"), item.get("max")
        if low is not None:
            out.append((name, cast(low), cast(low) - (1 if kind == "int" else 0.5)))
        if high is not None and high != low:
            out.append((name, cast(high), cast(high) + (1 if kind == "int" else 0.5)))
    return out

