#: The bench bands the cellar works to, per reading type. The reading type
#: itself is the declared vocabulary; the band is the domain rule.
PH_RANGE = (2.5, 4.5)
SO2_MAX_MG_L = 250.0
BRIX_RANGE = (0.0, 40.0)


def _scalars(record: Dict[str, Any]) -> Dict[str, Any]:
    return {
        key: value
        for key, value in record.items()
        if isinstance(value, (str, int, float, bool)) and value not in (None, "")
    }


def _domain_refusal(record: Dict[str, Any]) -> Optional[str]:
    reading_type = str(record.get("reading_type") or "")
    value = record.get("reading_value")
    if value is not None and float(value) < 0:
        return "reading_value cannot be negative"
    if value is None or not reading_type:
        return None
    number = float(value)
    if reading_type == "ph" and not PH_RANGE[0] <= number <= PH_RANGE[1]:
        return "ph must be between %.1f and %.1f for wine" % PH_RANGE
    if reading_type == "free_so2" and not 0.0 <= number <= SO2_MAX_MG_L:
        return "free_so2 must be between 0 and %.0f ppm" % SO2_MAX_MG_L
    if reading_type == "sugar" and not BRIX_RANGE[0] <= number <= BRIX_RANGE[1]:
        return "sugar must be between %.0f and %.0f brix" % BRIX_RANGE
    unit = str(record.get("unit") or "")
    expected = {
        "sugar": "brix",
        "ph": "ph_units",
        "titratable_acidity": "grams_per_litre",
        "free_so2": "ppm",
        "temperature": "celsius",
    }.get(reading_type)
    if expected and unit and unit != expected:
        return "%s is measured in %s" % (reading_type, expected)
    return None


def lab_record(record: Dict[str, Any]) -> Dict[str, Any]:
    """The compliance trail entry: what was measured, when, from where."""
    reading_type = str(record.get("reading_type") or "")
    value = record.get("reading_value")
    in_band = None
    if value is not None and reading_type:
        number = float(value)
        if reading_type == "ph":
            in_band = PH_RANGE[0] <= number <= PH_RANGE[1]
        elif reading_type == "free_so2":
            in_band = 0.0 <= number <= SO2_MAX_MG_L
        elif reading_type == "sugar":
            in_band = BRIX_RANGE[0] <= number <= BRIX_RANGE[1]
    return {
        "lot_code": record.get("lot_code"),
        "vessel_code": record.get("vessel_code"),
        "reading_type": reading_type or None,
        "reading_value": value,
        "unit": record.get("unit"),
        "reading_at": record.get("reading_at"),
        "source": record.get("source"),
        "addition_detail": record.get("addition_detail"),
        "lab_reference": record.get("lab_reference"),
        "in_band": in_band,
        "traceable": bool(record.get("source")),
        "instrument_exported": str(record.get("source") or "") == "instrument_export",
        "declared_connectors": [item["connector"] for item in connectors(CAPABILITY_ID)],
    }


def _plan(record: Dict[str, Any]) -> Tuple[Tuple[str, Dict[str, Any]], ...]:
    scalars = _scalars(record)
    lot = str(record.get("lot_code") or "unassigned")
    trail = lab_record(record)
    return (
        ("audit_chain", {"entry": {"lot_code": lot, "reading_type": record.get("reading_type")}}),
        ("database", {"table": ENTITY, "filters": {"lot_code": lot}}),
        ("documentation", {"title": "lot %s lab record" % lot, "sections": [{"fields": sorted(scalars)}]}),
        ("search", {"query": lot, "limit": 20}),
        ("pdf", {"content": "lot %s %s" % (lot, record.get("reading_type") or "reading"), "document": ENTITY}),
    )


def handle(payload: Dict[str, Any]) -> Dict[str, Any]:
    record = LotAndLabRecordKeeping.from_dict(payload)
    problem = _domain_refusal(record)
    if problem:
        return refused(CAPABILITY_ID, problem)
    results: Dict[str, Any] = {}
    failure = run_plan(execute, CAPABILITY_ID, record, _plan(record), results)
    if failure:
        return failure
    trail = lab_record(record)
    statement = "lot %s %s reading %s logged from %s" % (
        trail["lot_code"], trail["reading_type"], trail["reading_value"], trail["source"] or "unrecorded source",
    )
    return result_envelope(
        CAPABILITY_ID, 1, statement, result=trail, blocks=sorted(results),
        compliance_trail=[trail],
    )

